# Different theory: flood fill from top-left corner through 0s and 5s alike
# Then check which 0-components are NOT reachable from there (i.e., "trapped")

test_input = [
    [0, 5, 0, 0, 0, 0, 0, 5, 0, 0, 5, 0],
    [0, 5, 0, 0, 0, 5, 5, 5, 0, 5, 5, 0],
    [5, 5, 5, 0, 0, 5, 0, 5, 5, 5, 0, 0],
    [0, 0, 5, 5, 5, 5, 0, 5, 0, 5, 5, 0],
    [0, 0, 0, 5, 0, 0, 0, 5, 0, 0, 5, 0]
]

def bfs_reachable_from(start_r, start_c, grid):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    q = [(start_r, start_c)]
    while q:
        r, c = q.pop(0)
        if (r,c) in visited:
            continue
        visited.add((r,c))
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr,nc) not in visited:
                q.append((nr, nc))
    return visited

rows, cols = 5, 12
reachable_all = bfs_reachable_from(0, 0, test_input)

zero_components = []
visited_all_zero = set()
for r in range(rows):
    for c in range(cols):
        if test_input[r][c] == 0 and (r,c) not in visited_all_zero:
            comp = []
            q = [(r,c)]
            while q:
                cr, cc = q.pop(0)
                if (cr,cc) in visited_all_zero:
                    continue
                visited_all_zero.add((cr,cc))
                comp.append((cr,cc))
                for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < rows and 0 <= nc < cols and test_input[nr][nc] == 0 and (nr,nc) not in visited_all_zero:
                        q.append((nr, nc))
            zero_components.append(comp)

print("Zero components:")
for i, comp in enumerate(zero_components):
    print(f"Comp {i}: size={len(comp)}")

# Check which are not reachable from (0,0)
unreachable = []
for i, comp in enumerate(zero_components):
    unreachable_if_not_starting_early = not any(p in reachable_all for p in comp)
    if not unreachable_if_not_starting_early:
        # All cells in comp ARE reachable from start
        pass
    else:
        print(f"Comp {i} contains non-reachable-from-(0,0) cells: {[p for p in comp if p not in reachable_all]}")

# Better approach: mark "inside" by finding regions that are NOT reachable from outside
test_input = [
    [0, 5, 0, 0, 0, 0, 0, 5, 0, 0, 5, 0],
    [0, 5, 0, 0, 0, 5, 5, 5, 0, 5, 5, 0],
    [5, 5, 5, 0, 0, 5, 0, 5, 5, 5, 0, 0],
    [0, 0, 5, 5, 5, 5, 0, 5, 0, 5, 5, 0],
    [0, 0, 0, 5, 0, 0, 0, 5, 0, 0, 5, 0]
]

rows, cols = 5, 12

# First mark all cells reachable from any border position through 0s only
visited = [[False]*cols for _ in range(rows)]

# Start from all border cells that contain 0
q = []
for r in range(rows):
    if test_input[r][0] == 0:
        q.append((r, 0))
        visited[r][0] = True
    if test_input[r][cols-1] == 0:
        q.append((r, cols-1))
        visited[r][cols-1] = True
for c in range(cols):
    if test_input[0][c] == 0:
        q.append((0, c))
        visited[0][c] = True  
    if test_input[rows-1][c] == 0:
        q.append((rows-1, c))
        visited[rows-1][c] = True

from collections import deque
q = deque(q)

while q:
    r, c = q.popleft()
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < rows and 0 <= nc < cols:
            if not visited[nr][nc] and test_input[nr][nc] == 0:
                visited[nr][nc] = True
                q.append((nr, nc))

# Now find zero components that are NOT reachable from border (holes)
holes = []
for r in range(rows):
    for c in range(cols):
        if test_input[r][c] == 0 and not visited[r][c]:
            # Found a hole! BFS to find all connected 0s in this hole
            comp = []
            stack = [(r,c)]
            local_visited = {(r,c)}
            while stack:
                cr, cc = stack.pop()
                comp.append((cr, cc))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ncr, ncc = cr+dr, cc+dc
                    if 0 <= ncr < rows and 0 <= ncc < cols:
                        if test_input[ncr][ncc] == 0 and (ncr, ncc) not in local_visited and not visited[ncr][ncc]:
                            local_visited.add((ncr, ncc))
                            stack.append((ncr, ncc))
            if len(comp) > 0:
                holes.append(comp)

print(f"Holes found (zero-components not reachable from border): {len(holes)}")
for i, h in enumerate(holes):
    print(f"  Hole {i}: size={len(h)}, positions={h}")
